An authorization middleware reads a JWT from the `Authorization` header like this. What's the most serious flaw?

```typescript
import jwt from "jsonwebtoken";

function requireAdmin(req, res, next) {
  const token = req.headers.authorization?.replace("Bearer ", "");
  const payload = jwt.decode(token) as { sub: string; role: string };
  if (payload?.role !== "admin") return res.sendStatus(403);
  req.userId = payload.sub;
  next();
}
```

An API merges JSON request bodies into a settings object using this helper. An attacker sends `{"__proto__": {"isAdmin": true}}`. What happens?

```javascript
function merge(target, source) {
  for (const key in source) {
    if (typeof source[key] === "object" && source[key] !== null) {
      target[key] = merge(target[key] ?? {}, source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

merge({}, JSON.parse(req.body));
```

What's the vulnerability in this authenticated endpoint?

```typescript
app.get("/api/invoices/:id", requireAuth, async (req, res) => {
  const invoice = await db.invoice.findUnique({
    where: { id: req.params.id },
  });
  if (!invoice) return res.sendStatus(404);
  res.json(invoice);
});
```
